export type EnvKey = keyof typeof ENV_VARS;

const SPECS: Record<string, EnvVarSpec> = ENV_VARS;

/** One invalid variable. Never includes the value, which may be a secret. */
export interface EnvIssue {
  name: string;
  message: string;
}

export class EnvValidationError extends Error {
  constructor(readonly issues: EnvIssue[]) {
    super(
      `Invalid environment configuration (${issues.length} variable${issues.length === 1 ? "" : "s"}):\n` +
        issues.map((issue) => `  - ${issue.name}: ${issue.message}`).join("\n") +
        "\nSee backend/.env.example for every variable and its format.",
    );
    this.name = "EnvValidationError";
  }
}

/** Unset and empty are the same: dotenv turns `NAME=` into "". */
const valueOf = (source: NodeJS.ProcessEnv, name: string): string | undefined => {
  const value = source[name];
  return value === undefined || value.trim() === "" ? undefined : value;
};

/** Check every declared variable; return all issues instead of stopping at the first. */
export function checkEnv(source: NodeJS.ProcessEnv): EnvIssue[] {
  const issues: EnvIssue[] = [];
  for (const [name, spec] of Object.entries(SPECS)) {
    const value = valueOf(source, name);
    if (value === undefined) {
      if (spec.required) issues.push({ name, message: "is required but not set" });
      continue;
    }
    const result = spec.schema.safeParse(value);
    if (!result.success) {
      issues.push({ name, message: result.error.issues.map((issue) => issue.message).join("; ") });
    }
  }
  return issues;
}

/**
 * Fail fast at boot: throw one error listing every missing or malformed
 * variable, before any connection is opened or request served.
 */
export function validateEnv(source: NodeJS.ProcessEnv = process.env): void {
  const issues = checkEnv(source);
  if (issues.length > 0) throw new EnvValidationError(issues);
}

/**
 * The live process environment, for config modules that take an injectable
 * `env` argument (`getStellarConfig(env = processEnv)`) so tests can pass
 * their own.
 *
 * A forwarding proxy rather than `process.env` itself: tests may replace the
 * whole object (`process.env = { ...ORIGINAL_ENV }`), and a captured
 * reference would keep reading the old one.
 */
export const processEnv: NodeJS.ProcessEnv = new Proxy({} as NodeJS.ProcessEnv, {
  get: (_target, name) => (typeof name === "string" ? process.env[name] : undefined),
  has: (_target, name) => name in process.env,
  ownKeys: () => Reflect.ownKeys(process.env),
  getOwnPropertyDescriptor: (_target, name) => {
    const descriptor = Reflect.getOwnPropertyDescriptor(process.env, name);
    return descriptor && { ...descriptor, configurable: true };
  },
});

/**
 * Typed, read-through access to declared variables. Returns the raw string,
 * or `undefined` when unset; feature config modules own parsing and defaults.
 */
export const env: Readonly<Record<EnvKey, string | undefined>> = new Proxy({} as Record<EnvKey, string | undefined>, {
  get(_target, name) {
    if (typeof name !== "string" || !(name in SPECS)) {
      throw new Error(`Undeclared environment variable ${String(name)}: add it to backend/src/config/env.ts`);
    }
    return process.env[name];
  },
});
